def emit_call_instruction_indexed(
    func: ParsedFunction,
    kernel: IndexedFunctionKernel,
    call_id: int,
    module_symbols: PreparedModuleSymbols,
) -> list[str]:
    header: CompilerInt4 = kernel.call_header(call_id)
    span: CompilerInt4 = kernel.call_span(call_id)
    ret_type_id = header.first
    ret_kind_id = kernel.type_kind_id(ret_type_id)
    ret_is_aggregate = (
        ret_kind_id == TYPE_KIND_ARRAY
        or ret_kind_id == TYPE_KIND_STRUCT
    )
    ret_is_indirect = bool(
        ret_is_aggregate
        and aggregate_returned_indirect_indexed(kernel, ret_type_id)
    )
    callee = kernel.call_texts[header.second]
    is_indirect = bool(header.third & 1)
    is_vararg_call = bool(header.third & 2)
    arg_count = span.first
    fixed_arg_count = span.second
    dest_value_id = span.third
    dest = None if dest_value_id < 0 else kernel.value_name(dest_value_id)
    if not is_indirect and callee.startswith("llvm."):
        raise BackendUnavailable(
            "indexed regular-call lowering received an LLVM intrinsic"
        )
    if is_vararg_call and fixed_arg_count > arg_count:
        raise BackendUnavailable(
            f"self backend saw malformed variadic call in {func.name!r}: fixed args exceed actual args"
        )

    fixed_count = fixed_arg_count if is_vararg_call and not is_aarch64_linux_triple(module_symbols.target_triple) else arg_count
    stack_arg_entries: list[tuple[int, int]] = []
    indirect_stack_ptr_entries: list[tuple[int, int]] = []
    pending_indirect_stack_literals: list[tuple[int, int]] = []
    pending_indirect_reg_literals: list[tuple[int, str]] = []
    lines: list[str] = []
    stack_offset = 0
    gpr_index = 0
    fpr_index = 0
    arg_index = 0
    while arg_index < fixed_count:
        raw: CompilerInt4 = kernel.call_arg(header.fourth + arg_index)
        arg_type_id = raw.first
        arg_kind_id = kernel.type_kind_id(arg_type_id)
        arg_is_aggregate = (
            arg_kind_id == TYPE_KIND_ARRAY
            or arg_kind_id == TYPE_KIND_STRUCT
        )
        arg_is_indirect = bool(
            arg_is_aggregate
            and aggregate_passed_indirect_indexed(kernel, arg_type_id)
        )
        value = (
            kernel.value_name(raw.second)
            if raw.second >= 0
            else kernel.call_texts[raw.third]
        )
        if arg_kind_id == TYPE_KIND_VOID:
            register_code = 0
        elif arg_kind_id == TYPE_KIND_FP:
            register_code = 17
        elif not arg_is_aggregate:
            register_code = 9
        else:
            register_code = abi_register_code_indexed(kernel, arg_type_id)
        register_class = register_code // 8
        register_count = register_code % 8
        first_register_index = -1
        if register_class == 2:
            if fpr_index + register_count > 8:
                if arg_is_aggregate:
                    fpr_index = 8
                register_count = 0
            else:
                first_register_index = fpr_index
                fpr_index += register_count
        elif register_class == 1:
            if is_aarch64_linux_triple(module_symbols.target_triple) and not arg_is_indirect:
                argument_span: CompilerInt4 = kernel.type_span(arg_type_id)
                if argument_span.fourth >= 16:
                    gpr_index = _align_to(gpr_index, 2)
            if gpr_index + register_count > 8:
                register_count = 0
                if is_aarch64_linux_triple(module_symbols.target_triple):
                    gpr_index = 8
            else:
                first_register_index = gpr_index
                gpr_index += register_count
        if register_count == 0:
            if is_aarch64_linux_triple(module_symbols.target_triple):
                stack_offset = _align_to(stack_offset, stack_arg_alignment_indexed(kernel, arg_type_id))
            if arg_is_indirect:
                ptr_offset = stack_offset
                stack_offset += 8
                if _can_spill_aggregate_constant(value):
                    pending_indirect_stack_literals.append(
                        (ptr_offset, arg_index)
                    )
                else:
                    indirect_stack_ptr_entries.append(
                        (ptr_offset, arg_index)
                    )
            else:
                stack_arg_entries.append((stack_offset, arg_index))
                stack_offset += (
                    stack_arg_storage_size_indexed(kernel, arg_type_id)
                )
            arg_index += 1
            continue
        if arg_is_indirect:
            first_register = "x" + str(first_register_index)
            if _can_spill_aggregate_constant(value):
                pending_indirect_reg_literals.append(
                    (arg_index, first_register)
                )
            else:
                arg_type = kernel.type_desc(arg_type_id)
                lines.extend(
                    materialize_indirect_aggregate_arg_pointer(
                        func,
                        value,
                        arg_type,
                        first_register,
                        value_id=raw.second,
                    )
                )
            arg_index += 1
            continue
        if arg_is_aggregate:
            lines.extend(
                materialize_value(
                    func,
                    value,
                    kernel.type_desc(arg_type_id),
                    first_register_index,
                    module_symbols,
                    value_id=raw.second,
                )
            )
        else:
            lines.extend(
                materialize_scalar_value_indexed(
                    func,
                    kernel,
                    value,
                    arg_type_id,
                    first_register_index,
                    module_symbols,
                    value_id=raw.second,
                )
            )
        arg_index += 1

    while arg_index < arg_count:
        raw: CompilerInt4 = kernel.call_arg(header.fourth + arg_index)
        stack_arg_entries.append((stack_offset, arg_index))
        variadic_kind_id = kernel.type_kind_id(raw.first)
        stack_offset += (
            variadic_stack_arg_storage_size_indexed(kernel, raw.first)
        )
        arg_index += 1

    indirect_reg_literal_entries: list[tuple[int, int, str]] = []
    for indexed_arg, reg in pending_indirect_reg_literals:
        raw: CompilerInt4 = kernel.call_arg(header.fourth + indexed_arg)
        arg_span: CompilerInt4 = kernel.type_span(raw.first)
        stack_offset = _align_to(stack_offset, arg_span.fourth)
        temp_offset = stack_offset
        stack_offset += arg_span.third
        indirect_reg_literal_entries.append((temp_offset, indexed_arg, reg))
    indirect_stack_literal_entries: list[tuple[int, int, int]] = []
    for ptr_offset, indexed_arg in pending_indirect_stack_literals:
        raw: CompilerInt4 = kernel.call_arg(header.fourth + indexed_arg)
        arg_span: CompilerInt4 = kernel.type_span(raw.first)
        stack_offset = _align_to(stack_offset, arg_span.fourth)
        temp_offset = stack_offset
        stack_offset += arg_span.third
        indirect_stack_literal_entries.append(
            (ptr_offset, temp_offset, indexed_arg)
        )
    stack_size = _align_to(stack_offset, 16) if stack_offset else 0
    if ret_is_indirect:
        dest_offset = (
            -1
            if dest_value_id < 0
            else kernel.value_slot_offset(dest_value_id)
        )
        if dest_offset < 0:
            raise BackendUnavailable(
                f"self backend needs a materialized destination slot for large aggregate return in {func.name!r}"
            )
        lines.extend(emit_slot_base_address_parts(dest_offset, "x8"))
    if stack_size:
        lines.extend(emit_add_offset("sp", "sp", -stack_size, scratch_reg="x15"))
        for temp_offset, indexed_arg, reg in indirect_reg_literal_entries:
            raw: CompilerInt4 = kernel.call_arg(header.fourth + indexed_arg)
            arg_type = kernel.type_desc(raw.first)
            value = (
                kernel.value_name(raw.second)
                if raw.second >= 0
                else kernel.call_texts[raw.third]
            )
            lines.extend(emit_add_offset(reg, "sp", temp_offset, scratch_reg="x15"))
            lines.extend(
                store_large_aggregate_literal_to_address(
                    arg_type,
                    value,
                    reg,
                    data_reg_64="x12",
                    data_reg_32="w12",
                    module_symbols=module_symbols,
                )
            )
        for ptr_offset, temp_offset, indexed_arg in indirect_stack_literal_entries:
            raw: CompilerInt4 = kernel.call_arg(header.fourth + indexed_arg)
            arg_type = kernel.type_desc(raw.first)
            value = (
                kernel.value_name(raw.second)
                if raw.second >= 0
                else kernel.call_texts[raw.third]
            )
            lines.extend(emit_add_offset("x12", "sp", temp_offset, scratch_reg="x15"))
            lines.extend(
                store_large_aggregate_literal_to_address(
                    arg_type,
                    value,
                    "x12",
                    data_reg_64="x13",
                    data_reg_32="w13",
                    module_symbols=module_symbols,
                )
            )
            if ptr_offset:
                lines.extend(emit_add_offset("x14", "sp", ptr_offset, scratch_reg="x15"))
                lines.append(emitted_memory_instruction_line("str", "x12", "x14"))
            else:
                lines.append(emitted_memory_instruction_line("str", "x12", "sp"))
        for ptr_offset, indexed_arg in indirect_stack_ptr_entries:
            raw: CompilerInt4 = kernel.call_arg(header.fourth + indexed_arg)
            arg_type = kernel.type_desc(raw.first)
            value = (
                kernel.value_name(raw.second)
                if raw.second >= 0
                else kernel.call_texts[raw.third]
            )
            lines.extend(
                materialize_indirect_aggregate_arg_pointer(
                    func,
                    value,
                    arg_type,
                    "x12",
                    value_id=raw.second,
                )
            )
            if ptr_offset:
                lines.extend(emit_add_offset("x14", "sp", ptr_offset, scratch_reg="x15"))
                lines.append(emitted_memory_instruction_line("str", "x12", "x14"))
            else:
                lines.append(emitted_memory_instruction_line("str", "x12", "sp"))
        for offset, indexed_arg in stack_arg_entries:
            raw: CompilerInt4 = kernel.call_arg(header.fourth + indexed_arg)
            emit_kind_id = kernel.type_kind_id(raw.first)
            emit_value = (
                kernel.value_name(raw.second)
                if raw.second >= 0
                else kernel.call_texts[raw.third]
            )
            if (
                emit_kind_id == TYPE_KIND_ARRAY
                or emit_kind_id == TYPE_KIND_STRUCT
            ):
                lines.extend(
                    emit_vararg_stack_arg(
                        func,
                        kernel.type_desc(raw.first),
                        emit_value,
                        offset,
                        module_symbols,
                        value_id=raw.second,
                    )
                )
            else:
                lines.extend(
                    _emit_indexed_scalar_stack_arg(
                        func,
                        kernel,
                        emit_value,
                        raw.second,
                        raw.first,
                        offset,
                        module_symbols,
                    )
                )
    if call_id in func.aarch64_tail_call_ids:
        if is_indirect or is_vararg_call or stack_size or ret_is_aggregate:
            raise BackendUnavailable("invalid ABI in planned AArch64 scalar tail call")
        # The return terminator owns the frame restore and sibling transfer.
        # This jump has no ordinary post-call return PC in the current frame.
        return lines
    if is_indirect:
        callee_value_id = kernel.value_id(callee)
        lines.extend(
            materialize_pointer(
                func,
                callee,
                12,
                module_symbols,
                value_id=callee_value_id,
            )
        )
        lines.append("  blr x12")
    else:
        lines.append(
            emitted_direct_call_line(
                asm_symbol_prevalidated(callee, module_symbols)
            )
        )
    if stack_size:
        lines.extend(emit_add_offset("sp", "sp", stack_size, scratch_reg="x15"))
    dest_offset = (
        -1 if dest_value_id < 0 else kernel.value_slot_offset(dest_value_id)
    )
    if dest_offset >= 0 and not ret_is_indirect:
        slot_id = kernel.value_slot_id(dest_value_id)
        if slot_id < 0:
            raise BackendUnavailable(
                f"indexed call result slot is missing for {dest!r}"
            )
        slot_type_id = kernel.slot_type_id(slot_id)
        slot_header: CompilerInt4 = kernel.type_header(slot_type_id)
        if (
            slot_header.first == TYPE_KIND_ARRAY
            or slot_header.first == TYPE_KIND_STRUCT
        ):
            lines.extend(
                store_value_regs_to_slot_parts(
                    kernel.slot_offset(slot_id),
                    kernel.type_desc(slot_type_id),
                    0,
                )
            )
        else:
            # PCC_SELF_CALL_RESULT_REGISTERS: a result the allocator placed in
            # a pool register is committed with one move and its slot is left
            # unwritten, exactly like any other register-projected scalar.
            allocated_lines = commit_allocated_scalar_result_indexed(
                func,
                dest_value_id,
                ret_type_id,
                reg_name_indexed(kernel, ret_type_id, 0),
            )
            if allocated_lines is not None:
                lines.extend(allocated_lines)
            else:
                lines.extend(
                    _store_indexed_scalar_result(
                        kernel,
                        slot_id,
                        slot_type_id,
                    )
                )
    return lines

def emit_phi_assignments(
    func: ParsedFunction,
    *,
    source_block: str,
    target_block: str,
    module_symbols: PreparedModuleSymbols,
) -> list[str]:
    kernel = get_indexed_function_kernel(func)
    source_block_id = kernel.block_id(source_block)
    target_block_id = kernel.block_id(target_block)
    if source_block_id >= 0 and target_block_id >= 0:
        phi_fact: CompilerInt2 = kernel.block_phi_fact(target_block_id)
        all_scalar = True
        phi_index = 0
        while phi_index < phi_fact.second:
            indexed_phi: CompilerInt4 = kernel.phi_record(
                phi_fact.first + phi_index
            )
            indexed_phi_type: CompilerInt4 = kernel.type_header(
                indexed_phi.second
            )
            kind_id = indexed_phi_type.first
            if kind_id == TYPE_KIND_ARRAY or kind_id == TYPE_KIND_STRUCT:
                all_scalar = False
                break
            phi_index += 1
        if all_scalar:
            return _emit_phi_assignments_indexed(
                func,
                source_block_id=source_block_id,
                target_block_id=target_block_id,
                module_symbols=module_symbols,
            )
    target = text_key_mapping_get(func.block_map, target_block)
    if target is None and target_block_id >= 0:
        target = kernel.diagnostic_block(
            target_block_id,
            include_instructions=False,
        )
        func.block_map[target_block] = target
    if target is None:
        for block in func.blocks:
            if block.name == target_block:
                target = block
                break
    if target is None:
        raise BackendUnavailable(
            f"self backend branch targets unknown block {target_block!r} in {func.name!r}"
        )
    if not target.phis and target_block_id >= 0:
        phi_fact = kernel.block_phi_fact(target_block_id)
        projected = []
        phi_index = 0
        while phi_index < phi_fact.second:
            projected.append(kernel.diagnostic_phi(target_block_id, phi_index))
            phi_index += 1
        target.phis = tuple(projected)

    assignments = []
    temp_offset = 0
    for phi in target.phis:
        if not parsed_function_has_value_slot(func, phi.dest):
            continue
        match = None
        for incoming in phi.incoming:
            if incoming.label == source_block:
                match = incoming
                break
        if match is None:
            raise BackendUnavailable(
                f"self backend could not resolve phi incoming for {phi.dest!r} from {source_block!r}"
            )
        temp_align = max(1, min(phi.type.align, 8))
        temp_offset = _align_to(temp_offset, temp_align)
        assignments.append((phi, match, temp_offset))
        temp_offset += phi.type.slot_size

    if not assignments:
        return []

    # Scalar phi copies can be lowered as direct slot-to-slot stores when they
    # can be *ordered* so that no copy overwrites a slot another copy still
    # needs to read. Slot coalescing can put a phi source in the same physical
    # slot as a *different* phi's destination, so the safe order is computed
    # from slot offsets, not SSA names. When the copies form a cycle (a true
    # swap), no ordering is safe and we fall through to the temp-buffered path
    # below, which stages every source before writing any destination.
    if all(
        not phi.type.is_array and not phi.type.is_struct
        for phi, _match, _offset in assignments
    ):
        ordered = _order_scalar_phi_copies(func, assignments)
        if ordered is not None:
            lines: list[str] = []
            for phi, match in ordered:
                lines.extend(
                    materialize_value(func, match.value, phi.type, 9, module_symbols)
                )
                lines.extend(store_value_regs_to_value_slot(func, phi.dest, 9))
            return lines

    total_temp = _align_to(temp_offset, 16)
    lines: list[str] = []
    if total_temp:
        lines.extend(emit_stack_adjust(-total_temp))

    temp_addr_reg = "x13"

    def _emit_temp_addr(offset: int) -> list[str]:
        return emit_add_offset(temp_addr_reg, "sp", offset)

    for phi, match, offset in assignments:
        lines.extend(_emit_temp_addr(offset))
        if (phi.type.is_array or phi.type.is_struct) and not aggregate_fits_reg_abi(
            phi.type
        ):
            if match.value == "zeroinitializer":
                lines.extend(zero_address(temp_addr_reg, phi.type.slot_size))
            elif is_aggregate_literal_value(match.value):
                lines.extend(
                    store_large_aggregate_literal_to_address(
                        phi.type,
                        match.value,
                        temp_addr_reg,
                        module_symbols=module_symbols,
                    )
                )
            else:
                lines.extend(
                    materialize_aggregate_storage_address(
                        func, match.value, phi.type, "x14"
                    )
                )
                lines.extend(
                    copy_address_to_address("x14", temp_addr_reg, phi.type.slot_size)
                )
            continue
        lines.extend(materialize_value(func, match.value, phi.type, 9, module_symbols))
        lines.extend(store_value_to_address(temp_addr_reg, phi.type, 9))

    for phi, _match, offset in assignments:
        if (phi.type.is_array or phi.type.is_struct) and not aggregate_fits_reg_abi(
            phi.type
        ):
            lines.extend(_emit_temp_addr(offset))
            lines.extend(
                copy_address_to_value_slot(temp_addr_reg, func, phi.dest)
            )
            continue
        lines.extend(_emit_temp_addr(offset))
        lines.extend(load_value_from_address(temp_addr_reg, phi.type, 9))
        lines.extend(store_value_regs_to_value_slot(func, phi.dest, 9))

    if total_temp:
        lines.extend(emit_stack_adjust(total_temp))
    return lines

def emit_binop_indexed(
    kernel: IndexedFunctionKernel, op: str, type_id: int,
    lhs_register: int = 9, rhs_register: int = 10, result_register: int = 11,
) -> list[str]:
    header: CompilerInt4 = kernel.type_header(type_id)
    if header.first != TYPE_KIND_INT:
        raise BackendUnavailable(
            f"self backend only supports integer binops, got type_id={type_id}"
        )
    r9 = reg_name_indexed(kernel, type_id, lhs_register)
    r10 = reg_name_indexed(kernel, type_id, rhs_register)
    r11 = reg_name_indexed(kernel, type_id, result_register)
    if op == "add" or op == "sub":
        return [emitted_addsub_register_line(op, r11, r9, r10)]
    mapping = {
        "mul": f"  mul {r11}, {r9}, {r10}",
        "sdiv": f"  sdiv {r11}, {r9}, {r10}",
        "udiv": f"  udiv {r11}, {r9}, {r10}",
        "and": f"  and {r11}, {r9}, {r10}",
        "or": f"  orr {r11}, {r9}, {r10}",
        "xor": f"  eor {r11}, {r9}, {r10}",
        "shl": f"  lslv {r11}, {r9}, {r10}",
        "lshr": f"  lsrv {r11}, {r9}, {r10}",
        "ashr": f"  asrv {r11}, {r9}, {r10}",
    }
    # The quotient cannot overwrite either input before MSUB consumes it.
    quotient = reg_name_indexed(kernel, type_id, 11)
    if op == "srem":
        return [
            f"  sdiv {quotient}, {r9}, {r10}",
            f"  msub {r11}, {quotient}, {r10}, {r9}",
        ]
    if op == "urem":
        return [
            f"  udiv {quotient}, {r9}, {r10}",
            f"  msub {r11}, {quotient}, {r10}, {r9}",
        ]
    if op not in mapping:
        raise BackendUnavailable(f"self backend does not support binop {op!r}")
    return [mapping[op]]

def emit_function_prologue(
    func: ParsedFunction,
    module_symbols: PreparedModuleSymbols,
) -> list[str]:
    # Target-specific preparation belongs immediately before target emission.
    # The allocator is conservative and leaves every preassigned stack slot in
    # place, so an unsupported shape remains byte-for-byte on the spill path.
    allocate_aarch64_block_registers(func)
    symbol = asm_symbol(func.name, module_symbols)
    lines = ["", ".p2align 2"]
    if func.is_global:
        lines.append(f".globl {symbol}")
    lines.append(f"{symbol}:")
    linux = is_aarch64_linux_triple(module_symbols.target_triple)
    func.platform_frame_extra = 192 if linux and func.is_vararg else 0
    if linux and func.name == "_start":
        if len(func.args) != 1 or not func.args[0].type.is_ptr or not func.ret_type.is_void:
            raise ValueError("Linux _start requires void (ptr initial_stack)")
        lines.append("  mov x0, sp")
    if func.platform_frame_extra:
        func.aarch64_frameless = False
    func.aarch64_dynamic_stack = function_uses_dynamic_alloca(func)
    if func.aarch64_dynamic_stack:
        func.aarch64_frameless = False
        if func.platform_frame_extra:
            # The va_list register save area is addressed from SP.
            raise BackendUnavailable(
                f"self backend cannot combine a dynamic alloca with the Linux "
                f"variadic register save area in {func.name!r}"
            )
    # AArch64 branch protection (pac-ret + BTI). ``paciasp`` signs LR (x30) with
    # SP as the modifier *before* the frame save stores it, and doubles as a BTI
    # ``c`` landing pad for ``bl``/``blr`` callers. The matching ``autiasp`` is
    # emitted in the epilogue after LR is reloaded. See
    # ``self_backend_aarch64_darwin_branch_protection`` for the S-track rationale
    # (self backend must not depend on the LLVM path for CFI hardening).
    if func.aarch64_frameless:
        # No frame record and no stack: LR never leaves x30, so there is
        # nothing to sign; ``bti c`` keeps the indirect-call landing pad that
        # ``paciasp`` otherwise provides.
        if branch_protection_enabled():
            lines.append(emitted_fixed_instruction_line("bti c"))
    else:
        if branch_protection_enabled():
            lines.extend(prologue_sign_return_address(func))
        lines.extend(
            [
                emitted_frame_pair_line(False),
                emitted_move_register_line("x29", "sp"),
            ]
        )
        total_frame = func.frame_size + callee_saved_area_size(func) + func.platform_frame_extra
        if total_frame:
            lines.extend(emit_stack_adjust(-total_frame))
        # Save before any argument is committed into a callee-saved register.
        lines.extend(emit_callee_saved_stores(func))
    if func.platform_frame_extra:
        # Preserve incoming variadic registers before normal argument lowering.
        for index in range(8):
            lines.append(f"  str x{index}, [sp, #{index * 8}]")
            lines.append(f"  str q{index}, [sp, #{64 + index * 16}]")
    kernel = get_indexed_function_kernel(func)
    if func.indexed_slot_projection and kernel.hidden_sret_slot_id >= 0:
        hidden_slot_id = kernel.hidden_sret_slot_id
        lines.extend(
            store_reg_to_slot_parts(
                "x8",
                kernel.slot_offset(hidden_slot_id),
                kernel.type_desc(kernel.slot_type_id(hidden_slot_id)),
            )
        )
    elif func.hidden_sret_slot is not None:
        lines.extend(store_reg_to_slot("x8", func.hidden_sret_slot))

    arg_types = [arg.type for arg in func.args]
    arg_regs = assign_abi_arg_regs(arg_types, linux=linux)
    stack_offsets = stack_arg_offsets(arg_types, arg_regs, linux=linux)
    for arg, regs, stack_offset in zip(func.args, arg_regs, stack_offsets):
        if not parsed_function_has_value_slot(func, arg.name):
            continue
        if not regs:
            assert stack_offset is not None
            lines.extend(emit_fixed_stack_arg_load(func, arg, stack_offset))
            continue
        if aggregate_passed_indirect(arg.type):
            lines.extend(copy_address_to_value_slot(regs[0], func, arg.name))
            continue
        if func.indexed_slot_projection:
            arg_value_id = kernel.value_id(arg.name)
            arg_type_id = kernel.value_type_id(arg_value_id)
            arg_header = kernel.type_header(arg_type_id)
            if arg_header.first in (
                TYPE_KIND_INT,
                TYPE_KIND_FP,
                TYPE_KIND_PTR,
            ):
                allocated_lines = commit_allocated_scalar_result_indexed(
                    func,
                    arg_value_id,
                    arg_type_id,
                    reg_name_indexed(kernel, arg_type_id, int(regs[0][1:])),
                )
                if allocated_lines is not None:
                    lines.extend(allocated_lines)
                    continue
                lines.extend(
                    store_scalar_reg_to_value_slot_indexed(
                        func,
                        arg_value_id,
                        arg_type_id,
                        int(regs[0][1:]),
                    )
                )
                continue
        lines.extend(
            store_value_regs_to_value_slot(func, arg.name, int(regs[0][1:]))
        )
    return lines

def _candidate_indexed_definition_type_id(
    kernel: IndexedFunctionKernel,
    kind_id: int,
    record_id: int,
    dest_id: int,
) -> int:
    raw: CompilerInt4 = kernel.instruction_record(record_id)
    if kind_id == PARSED_INSTRUCTION_KIND_LOAD:
        header: CompilerInt4 = kernel.type_header(raw.first)
        return (
            raw.first
            if header.first == TYPE_KIND_INT or header.first == TYPE_KIND_PTR
            else -1
        )
    if kind_id == PARSED_INSTRUCTION_KIND_BINOP:
        binop_type: CompilerInt4 = kernel.type_header(raw.second)
        return (
            raw.second
            if binop_type.first == TYPE_KIND_INT
            else -1
        )
    if kind_id == PARSED_INSTRUCTION_KIND_ICMP:
        compared: CompilerInt4 = kernel.type_header(raw.second)
        if compared.first != TYPE_KIND_INT and compared.first != TYPE_KIND_PTR:
            return -1
        return -1 if dest_id < 0 else kernel.value_type_id(dest_id)
    if kind_id == PARSED_INSTRUCTION_KIND_CAST:
        src_header: CompilerInt4 = kernel.type_header(raw.second)
        dst_header: CompilerInt4 = kernel.type_header(raw.fourth)
        src_kind = src_header.first
        dst_kind = dst_header.first
        if (
            (src_kind == TYPE_KIND_INT or src_kind == TYPE_KIND_PTR)
            and (dst_kind == TYPE_KIND_INT or dst_kind == TYPE_KIND_PTR)
        ):
            return raw.fourth
        return -1
    result_header: CompilerInt4 = kernel.type_header(raw.first)
    result_kind = result_header.first
    return (
        raw.first
        if result_kind == TYPE_KIND_INT or result_kind == TYPE_KIND_PTR
        else -1
    )

def _register_type_ids_match(
    kernel: IndexedFunctionKernel, left_id: int, right_id: int
) -> bool:
    if left_id == right_id:
        return True
    left: CompilerInt4 = kernel.type_header(left_id)
    right: CompilerInt4 = kernel.type_header(right_id)
    return left.first == TYPE_KIND_PTR and right.first == TYPE_KIND_PTR

def emit_return_terminator_indexed(
    func: ParsedFunction,
    *,
    kernel: IndexedFunctionKernel,
    type_id: int,
    value_ref: int,
    module_symbols: PreparedModuleSymbols,
) -> list[str]:
    value = kernel.terminator_value(value_ref)
    header: CompilerInt4 = kernel.type_header(type_id)
    if aggregate_returned_indirect_indexed(kernel, type_id):
        return emit_return_terminator(
            func,
            ret_type=kernel.type_desc(type_id),
            value=value,
            module_symbols=module_symbols,
            value_id=value_ref,
        )
    if header.first in (TYPE_KIND_INT, TYPE_KIND_FP, TYPE_KIND_PTR):
        lines = materialize_scalar_value_indexed(
            func,
            kernel,
            value,
            type_id,
            0,
            module_symbols,
            value_id=value_ref,
        )
        lines.extend(emit_epilogue(func))
        return lines
    return emit_return_terminator(
        func,
        ret_type=kernel.type_desc(type_id),
        value=value,
        module_symbols=module_symbols,
        value_id=value_ref,
    )

